private static final String HOLD_TO_AIM = "item_patterns/hold_to_aim";
private static final String USE_TO_AIM = "item_patterns/use_to_aim";
private volatile ItemPatternSet snapshot = ItemPatternSet.empty();

MinecraftItemPatternReloadListener() {
}

ItemPatternSet snapshot() {
    return this.snapshot;
}

void loadImmediately(ResourceManager resourceManager) {
    this.replace(this.load(resourceManager));
}

protected ItemPatternSet prepare(ResourceManager resourceManager, ProfilerFiller profiler) {
    return this.load(resourceManager);
}

protected void apply(ItemPatternSet preparations, ResourceManager resourceManager, ProfilerFiller profiler) {
    this.replace(preparations);
}

private ItemPatternSet load(ResourceManager resourceManager) {
    try {
        return new ItemPatternSet(this.loadDirectory(resourceManager, HOLD_TO_AIM), this.loadDirectory(resourceManager, USE_TO_AIM));
    }
    catch (RuntimeException exception) {
        ThirdPerson.LOGGER.error("Could not scan item-pattern resources; keeping previous rules", (Throwable)exception);
        return this.snapshot;
    }
}

private List<String> loadDirectory(ResourceManager resourceManager, String directory) {
    ArrayList<String> patterns = new ArrayList<String>();
    resourceManager.m_214159_(directory, id -> id.m_135815_().endsWith(".json")).entrySet().stream().sorted(Comparator.comparing(entry -> ((ResourceLocation)entry.getKey()).toString())).forEach(entry -> {
        ResourceLocation resourceId = (ResourceLocation)entry.getKey();
        try (BufferedReader reader = ((Resource)entry.getValue()).m_215508_();){
            patterns.addAll(ItemPatternJsonCodec.decode(JsonParser.parseReader((Reader)reader)));
        }
        catch (Exception exception) {
            ThirdPerson.LOGGER.error("Ignoring invalid item-pattern resource {}: {}", (Object)resourceId, (Object)exception.getMessage());
        }
    });
    return patterns;
}

