import io.github.leawind.thirdperson.internal.logic.scheduler.rotation.PlayerRotationState;
import io.github.leawind.thirdperson.internal.logic.scheduler.rotation.PlayerRotationTarget;
import java.util.Objects;

public final class PlayerRotationStrategy {
    private PlayerRotationStrategy() {
    }

    public static PlayerRotationDecision resolve(PlayerRotationState state) {
        Objects.requireNonNull(state, "state");
        if (state.interacting()) {
            return PlayerRotationStrategy.immediate(PlayerRotationTarget.CAMERA_HIT_RESULT);
        }
        if (state.aiming()) {
            return PlayerRotationStrategy.immediate(PlayerRotationTarget.PREDICTED_TARGET_ENTITY);
        }
        switch (state.normalMode()) {
            case CAMERA_CROSSHAIR: {
                return PlayerRotationStrategy.immediate(PlayerRotationTarget.CAMERA_HIT_RESULT);
            }
            case PARALLEL_WITH_CAMERA: {
                return PlayerRotationStrategy.smooth(PlayerRotationTarget.CAMERA_ROTATION, 0.0);
            }
            case NONE: {
                return PlayerRotationStrategy.smooth(PlayerRotationTarget.CURRENT_ROTATION, 0.0);
            }
        }
        if (state.fallFlying()) {
            return PlayerRotationStrategy.immediate(PlayerRotationTarget.CAMERA_ROTATION);
        }
        if (state.swimming()) {
            return PlayerRotationStrategy.smooth(PlayerRotationTarget.IMPULSE_DIRECTION, 0.01);
        }
        if (state.sprinting()) {
            return PlayerRotationStrategy.smooth(PlayerRotationTarget.HORIZONTAL_IMPULSE_DIRECTION, 0.025);
