public static ThirdPersonPersistentState defaults() {
    return new ThirdPersonPersistentState(2, new CameraState(CameraSettings.defaultNormalProfile(), CameraSettings.defaultAimingProfile(), CameraSettings.defaultSmoothing()), new AimingState(true, List.of(), List.of()), new PlayerState(NormalPlayerRotationMode.INTEREST_POINT, true, true, RaycastOrigin.CAMERA), new SoundState(false), new HudState(CrosshairMode.ALWAYS, true));
}

public static ThirdPersonPersistentState extract(SchedulerRuntime runtime) {
    Objects.requireNonNull(runtime, "runtime");
    CameraSettings camera = runtime.cameraSettings();
    AimingSettings aiming = runtime.aimingSettings();
    PlayerSettings player = runtime.playerSettings();
    SoundSettings sound = runtime.soundSettings();
    return new ThirdPersonPersistentState(2, new CameraState(camera.normalProfile(), camera.aimingProfile(), camera.smoothing()), new AimingState(aiming.smartAiming(), aiming.holdToAimItemPatterns(), aiming.useToAimItemPatterns()), new PlayerState(player.normalMode(), player.autoRotateInteracting(), player.doNotRotateWhenEating(), player.raycastOrigin()), new SoundState(sound.centerCameraEntitySounds()), new HudState(runtime.hudSettings().crosshairMode(), runtime.hudSettings().hideCrosshairWhenFallFlyingAndNotAiming()));
}

public void applyTo(SchedulerRuntime runtime) {
    Objects.requireNonNull(runtime, "runtime");
    runtime.cameraSettings().restore(this.camera.normal(), this.camera.aiming(), this.camera.smoothing());
    runtime.aimingSettings().restore(this.aiming.smartAiming(), this.aiming.holdToAimItemPatterns(), this.aiming.useToAimItemPatterns());
    runtime.playerSettings().restore(this.player.normalMode(), this.player.autoRotateInteracting(), this.player.doNotRotateWhenEating(), this.player.raycastOrigin());
    runtime.soundSettings().setCenterCameraEntitySounds(this.sound.centerCameraEntitySounds());
    runtime.hudSettings().restore(this.hud.crosshair(), this.hud.hideCrosshairWhenFallFlyingAndNotAiming());
}

public record CameraState(CameraProfile normal, CameraProfile aiming, CameraSmoothing smoothing) {
    public CameraState {
        Objects.requireNonNull(normal, "normal");
        Objects.requireNonNull(aiming, "aiming");
        Objects.requireNonNull(smoothing, "smoothing");
    }
}

public record AimingState(boolean smartAiming, List<String> holdToAimItemPatterns, List<String> useToAimItemPatterns) {
    private static final int MAX_PATTERNS_PER_LIST = 1024;

    public AimingState {
        holdToAimItemPatterns = AimingState.copyPatterns(holdToAimItemPatterns, "holdToAimItemPatterns");
        useToAimItemPatterns = AimingState.copyPatterns(useToAimItemPatterns, "useToAimItemPatterns");
    }

    private static List<String> copyPatterns(List<String> patterns, String name) {
        Objects.requireNonNull(patterns, name);
        if (patterns.size() > 1024 || patterns.stream().anyMatch(Objects::isNull)) {
            throw new IllegalArgumentException(name + " must contain at most 1024 non-null values");
        }
        return List.copyOf(patterns);
    }
}

